script:
country_event = {
	id = unplugged.199
	is_triggered_only = yes
	hide_window = yes
	trigger = {
		has_origin = origin_unplugged
	}
	immediate = {
		set_variable = {
			which = var_unplugged_cybernetic_benefits
			value = 3
		}
		set_variable = {
			which = var_unplugged_cybernetic_negatives
			value = 3
		}

		every_owned_leader = {
			limit = {
				leader_class = commander
				is_ruler = no
			}
			add_trait = {
				trait = leader_trait_unplugged_cybernetic_positives_3
				show_message = no
			}
		}

		species = {
			set_species_flag = unplugged_species
		}

		capital_star = {
			event_target:origin_unplugged_assimilator_empire = {
				create_fleet = {
					name = NAME_Exigency_Fleet
					effect = {
						set_owner = event_target:origin_unplugged_assimilator_empire
						while = {
							count = 3
							create_ship = {
								name = random
								design = "NAME_Unplugged_Machine_Legacy_Corvette"
								prefix = no
							}
						}
						set_location = PREVPREV
						set_fleet_stance = aggressive
						set_aggro_range_measure_from = self
						set_aggro_range = 400
						set_fleet_flag = unplugged_starting_civilwar_fleet_flag
					}
				}
			}
			create_ambient_object = {
				type = medium_debris_02_object
			}
			create_ambient_object = {
				type = abandoned_ship_2_object
			}
			solar_system = {
				every_system_planet = {
					limit = {
						has_carrier_flag = unplugged_homeworld
					}
					while = {
						count = 10
						create_army = {
							name = random
							owner = root
							species = root
							type = "assault_army"
						}
					}
				}
			}
		}
	}
}

